-- 线性表模块：单链表结点、头指针与已知前驱时的更新边界。
INSERT INTO knowledge_point (name,description,course_id,parent_id,content_key,content_source,content_version,content_review_status,sort_order,deleted)
SELECT '单链表的结点与表示','结点保存数据和 next 指针，物理地址可以离散；按位定位需从头遍历，已知前驱时插删可为 O(1)。',course.id,parent.id,'cs408-singly-linked-list','AISTU',1,'REVIEWED',4,0 FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-linear-lists' LEFT JOIN knowledge_point existing ON existing.content_key='cs408-singly-linked-list' WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id,content_key,content_version,review_status,title,lesson_json,check_json)
SELECT point.id,'cs408-singly-linked-list',1,'REVIEWED','单链表的结点与表示',JSON_OBJECT('summary','单链表结点由数据域和 next 指针组成，头指针标识首结点，可选择头结点作为不保存业务数据的哨兵。结点可离散分布；按位定位必须从头沿 next 遍历，已知前驱时的局部插删才是 O(1)。','steps',JSON_ARRAY('每个结点保存数据与唯一后继入口','物理地址可以离散，逻辑顺序由 next 决定','从表头沿指针才能定位第 i 个结点','已知前驱与按位定位是不同前提'),'prerequisite',JSON_OBJECT('contentKey','cs408-linear-list-definition-operations','title','线性表的定义与基本操作','description','先确认链表仍实现同一个线性表逻辑序列。'),'nextStep',JSON_OBJECT('contentKey','cs408-linked-list-insert-delete','title','链表结点的插入与删除','description','继续学习如何安全改接局部指针。')),JSON_OBJECT('id','singly-linked-list-v1','prompt','单链表按逻辑位置访问中间结点通常为什么是 O(n)？','options',JSON_ARRAY(JSON_OBJECT('id','TRAVERSE_NEXT','text','必须从头指针沿 next 逐结点遍历'),JSON_OBJECT('id','POINTER_SIZE','text','因为 next 指针占用的字节数随 n 线性增加')),'correctOptionId','TRAVERSE_NEXT','correctExplanation','正确：单链表没有按下标计算物理地址的连续存储性质。','incorrectExplanation','不正确：定位时间来自遍历路径长度，而不是指针字段大小。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='cs408-singly-linked-list' AND existing.content_version=1 WHERE point.content_key='cs408-singly-linked-list' AND existing.id IS NULL;
